 readonly DatabaseFixture db=new();public async Task InitializeAsync(){await db.InitializeAsync();await S("UPDATE platform.document_jobs SET state='FAILED',last_error='test_cleanup',lease_token=NULL,lease_until=NULL WHERE state IN('QUEUED','PROCESSING','RETRY','UNKNOWN')");}public Task DisposeAsync()=>db.DisposeAsync();
 Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);static JsonElement E(object x)=>JsonSerializer.SerializeToElement(x);static Guid Id(JsonElement x)=>x.GetProperty("id").GetGuid();static long V(JsonElement x)=>x.GetProperty("version").GetInt64();
 async Task<DateOnly> Today()=>DateOnly.Parse((string)(await S("SELECT ((now()AT TIME ZONE timezone)::date)::text FROM core.companies WHERE id=@c",("c",db.Company)))!);
 async Task<JsonElement> Definition(string kind="PROFIT_LOSS",string[]? columns=null){var today=await Today();object filter=kind is "BALANCE_SHEET"or"AR_AGING"or"AP_AGING"?new{asOf=today}:new{from=today,to=today.AddDays(1)};return columns is null?E(new{kind,filters=filter}):E(new{kind,filters=filter,columns});}
 async Task<JsonElement> Pack(HttpClient c,params JsonElement[] defs)=>await Expect(await Send(c,HttpMethod.Post,"/reports/packs",new ReportPackInput("HTT test report pack",defs.Select(d=>E(new{definition=d})).ToArray())),HttpStatusCode.Created);
 Task<JsonElement> ViewPack(HttpClient c,Guid id)=>Get(c,$"/reports/packs/{id}");
 async Task<Guid> Saved(HttpClient c,JsonElement d,string visibility="PRIVATE")=>await Create(c,"/reports/saved",new SavedReportInput("Report favourite",d,visibility));
 async Task<Guid> Pdf(HttpClient c,Guid id,string? key=null)=>Id(await Expect(await Send(c,HttpMethod.Post,$"/documents/{id}/pdf",version:1,key:key),HttpStatusCode.Accepted));
 sealed class Stub:IFileScanner,IDocumentMailer,IPdfRenderer
 {public bool Fail;public WorkFailure Failure=WorkFailure.Retry;public Action? During;public Task<byte[]> RenderAsync(JsonElement s,CancellationToken ct){During?.Invoke();if(Fail)throw new DocumentWorkException("test_pdf_retry",Failure);return Task.FromResult("%PDF-1.4\n%%EOF"u8.ToArray());}public Task<bool> IsCleanAsync(byte[] x,CancellationToken ct)=>throw new InvalidOperationException("Unexpected scan");public Task<string> SendAsync(Guid id,JsonElement x,CancellationToken ct)=>throw new InvalidOperationException("Unexpected mail");}
 async Task<bool> Work(Stub stub){await using var source=NpgsqlDataSource.Create(db.Worker);return await new DocumentWorker(source,stub,stub,stub).ProcessOneAsync();}
 [Theory][InlineData("PROFIT_LOSS")][InlineData("BALANCE_SHEET")][InlineData("AR_AGING")][InlineData("AP_AGING")][InlineData("CASH_FLOW")][InlineData("PURCHASING")][InlineData("ARAP")][InlineData("INVENTORY")][InlineData("BANKING")][InlineData("SALES")]
 public async Task Every_source_has_bounded_native_snapshot_without_economic_writes(string kind)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var before=await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@c",("c",db.Company));var pack=await Pack(c,await Definition(kind));var sections=pack.GetProperty("snapshot").GetProperty("sections");Assert.Single(sections.EnumerateArray());Assert.Equal(kind,sections[0].GetProperty("kind").GetString());Assert.Equal(64,pack.GetProperty("sha256").GetString()!.Length);Assert.Equal(before,await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@c",("c",db.Company)));Assert.Equal(pack.GetRawText(),(await ViewPack(c,Id(pack))).GetRawText());}
 [Fact]public async Task Saved_report_is_private_by_default_company_share_is_read_only_and_favourites_are_personal()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Definition();var id=await Saved(c,d);var staff=await Staff(db,"FINANCE");using var user=api.Authenticated(staff.Subject);await Expect(await user.GetAsync($"/api/v1/reports/saved/{id}"),HttpStatusCode.NotFound);Assert.Equal(0,(await Get(user,"/reports/saved")).GetProperty("totalCount").GetInt32());await Expect(await Send(c,HttpMethod.Put,$"/reports/saved/{id}",new SavedReportInput("Shared report",d,"COMPANY"),1),HttpStatusCode.OK);await Expect(await Send(user,HttpMethod.Put,$"/reports/saved/{id}/favourite",new ReportFavouriteInput(true)),HttpStatusCode.OK);Assert.Equal(1,(await Get(user,"/reports/saved?favourites=true")).GetProperty("totalCount").GetInt32());Assert.Equal(0,(await Get(c,"/reports/saved?favourites=true")).GetProperty("totalCount").GetInt32());await Expect(await Send(user,HttpMethod.Put,$"/reports/saved/{id}",new SavedReportInput("Steal",d,"COMPANY"),2),HttpStatusCode.NotFound);await Expect(await Send(c,HttpMethod.Put,$"/reports/saved/{id}",new SavedReportInput("Private again",d),2),HttpStatusCode.OK);Assert.Equal(0,(await Get(user,"/reports/saved?favourites=true")).GetProperty("totalCount").GetInt32());}
 [Fact]public async Task Immutable_versions_and_archive_restore_do_not_change_frozen_packs()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Definition();var id=await Saved(c,d);var x=await Expect(await Send(c,HttpMethod.Post,"/reports/packs",new ReportPackInput("Version one",[E(new{savedReportId=id,version=1})])),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Put,$"/reports/saved/{id}",new SavedReportInput("Archived",d,Active:false),1),HttpStatusCode.OK);Assert.Empty((await Get(c,"/reports/saved")).GetProperty("items").EnumerateArray());await Expect(await Send(c,HttpMethod.Put,$"/reports/saved/{id}",new SavedReportInput("Restored",d),2),HttpStatusCode.OK);Assert.Equal(3L,await S("SELECT count(*)FROM reporting.saved_versions WHERE company_id=@c AND report_id=@id",("c",db.Company),("id",id)));Assert.Equal(x.GetProperty("sha256").GetString(),(await ViewPack(c,Id(x))).GetProperty("sha256").GetString());await Expect(await Send(c,HttpMethod.Post,"/reports/packs",new ReportPackInput("Stale",[E(new{savedReportId=id,version=1})])),HttpStatusCode.Conflict);}
 [Fact]public async Task Format_is_personal_versioned_and_frozen_into_output()
 {await using var api=new TestApi(db);using var c=api.Authenticated();Assert.Equal(0,V(await Get(c,"/reports/settings")));await Expect(await Send(c,HttpMethod.Put,"/reports/settings",new ReportFormatInput(E(new{header="HTT SAMPLE",footer="CONFIDENTIAL SAMPLE",currency="AUD",basis="SOURCE_DEFINED",decimalPlaces=0,negativeStyle="PARENTHESES"})),0),HttpStatusCode.OK);var pack=await Pack(c,await Definition());Assert.Equal(0,pack.GetProperty("snapshot").GetProperty("format").GetProperty("decimalPlaces").GetInt32());await Expect(await Send(c,HttpMethod.Put,"/reports/settings",new ReportFormatInput(E(new{decimalPlaces=2})),0),HttpStatusCode.Conflict);var other=await Staff(db,"FINANCE");using var user=api.Authenticated(other.Subject);Assert.Equal(0,V(await Get(user,"/reports/settings")));}
