 public async Task Definition_whitelists_reject_arbitrary_columns_filters_and_dates(string mode)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=JsonNode.Parse((await Definition()).GetRawText())!;switch(mode){case"unknown_column":d["columns"]=new JsonArray("password");break;case"duplicate_columns":d["columns"]=new JsonArray("name","name");break;case"filter_sql":d["filters"]!["sql"]="SELECT secret";break;case"invalid_date":d["filters"]!["from"]="2026-99-99";break;case"infinite_date":d["filters"]!["to"]="infinity";break;case"too_many_columns":d["columns"]=new JsonArray(Enumerable.Repeat("name",9).Select(x=>(JsonNode?)JsonValue.Create(x)).ToArray());break;}await Expect(await Send(c,HttpMethod.Post,"/reports/saved",new SavedReportInput("Bad config",E(d))),HttpStatusCode.UnprocessableEntity);}
