 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=await Saved(c,await Definition(),"COMPANY");var pack=await Pack(c,await Definition());using var other=api.Authenticated(company:db.OtherCompany);await Expect(await other.GetAsync($"/api/v1/reports/packs/{Id(pack)}"),HttpStatusCode.NotFound);var staff=await Staff(db,"FINANCE");using var user=api.Authenticated(staff.Subject);await Expect(await user.GetAsync($"/api/v1/reports/packs/{Id(pack)}"),HttpStatusCode.NotFound);await S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code='accounting.ledger.read'",("c",db.Company));Assert.Empty((await Get(c,"/reports/saved")).GetProperty("items").EnumerateArray());await Expect(await c.GetAsync($"/api/v1/reports/packs/{Id(pack)}"),HttpStatusCode.Forbidden);await Expect(await c.GetAsync($"/api/v1/reports/saved/{id}"),HttpStatusCode.Forbidden);}
 [Fact]public async Task Concurrent_same_key_capture_and_pdf_requests_create_one_artifact_each()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var input=new ReportPackInput("Same pack",[E(new{definition=await Definition()})]);var key=Code();var responses=await Task.WhenAll(Enumerable.Range(0,3).Select(_=>Send(c,HttpMethod.Post,"/reports/packs",input,key:key)));var ids=new List<Guid>();foreach(var r in responses)ids.Add(Id(await Expect(r,HttpStatusCode.Created)));Assert.Single(ids.Distinct());var jobs=await Task.WhenAll(Pdf(c,ids[0]),Pdf(c,ids[0]));Assert.Equal(jobs[0],jobs[1]);Assert.Equal(1L,await S("SELECT count(*)FROM reporting.packs WHERE company_id=@c",("c",db.Company)));Assert.Equal(1L,await S("SELECT count(*)FROM platform.document_jobs WHERE company_id=@c AND kind='PDF'",("c",db.Company)));}
 [Fact]public async Task Pdf_retry_renders_frozen_payload_not_live_report_and_download_rechecks_rights()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var pack=await Pack(c,await Definition());var id=Id(pack);var job=await Pdf(c,id);var stub=new Stub{Fail=true};await Work(stub);Assert.Equal("RETRY",(await Get(c,$"/document-jobs/{job}")).GetProperty("state").GetString());await S("UPDATE platform.document_jobs SET available_at=now()WHERE id=@id",("id",job));stub.Fail=false;await Work(stub);var done=await Get(c,$"/document-jobs/{job}");Assert.Equal("SUCCEEDED",done.GetProperty("state").GetString());var file=done.GetProperty("outputFileId").GetGuid();Assert.Equal(HttpStatusCode.OK,(await c.GetAsync($"/api/v1/files/{file}/content")).StatusCode);await S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code='accounting.ledger.read'",("c",db.Company));await Expect(await c.GetAsync($"/api/v1/files/{file}/content"),HttpStatusCode.Forbidden);}
