 {await using var api=new TestApi(db);using var c=api.Authenticated();var pack=await Pack(c,await Definition());var job=await Pdf(c,Id(pack));var stub=new Stub{During=()=>S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code='accounting.ledger.read'",("c",db.Company)).GetAwaiter().GetResult()};await Work(stub);Assert.Equal("FAILED",await S("SELECT state FROM platform.document_jobs WHERE id=@id",("id",job)));Assert.Equal(0L,await S("SELECT count(*)FROM platform.file_assets WHERE company_id=@c",("c",db.Company)));}
