 async Task<JsonElement> Expense(HttpClient c,decimal amount=100,string basis="NON_CASH")
 {
  await S("UPDATE core.companies SET gst_registered=true,gst_basis=@b WHERE id=@c",("c",db.Company),("b",basis));var supplier=await Create(c,"/suppliers",new SupplierMaintenance(Code(),"Designer test supplier",null));
  var account=(Guid)(await S("INSERT INTO accounting.accounts(company_id,code,name,kind)VALUES(@c,@code,'Designer expenses','EXPENSE')RETURNING id",("c",db.Company),("code",Code())))!;
  var tax=(Guid)(await S("SELECT id FROM accounting.tax_codes WHERE company_id=@c AND code='GST'",("c",db.Company)))!;var today=await Today();
  return await Expect(await Send(c,HttpMethod.Post,"/supplier-expense-bills",new ExpenseBillInput(supplier,Code(),today,today.AddDays(30),today,[new(account,"Actual test expense",amount,amount/10,tax)],"Current test evidence",today)),HttpStatusCode.Created);
 }
 [Theory][InlineData("CASH")][InlineData("NON_CASH")]
 public async Task Native_totals_match_real_AP_GL_GST_and_frozen_pack_survives_later_payment(string basis)
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var bill=await Expense(c,basis:basis);
  var defs=await Task.WhenAll(new[]{"PROFIT_LOSS","BALANCE_SHEET","AP_AGING","CASH_FLOW","PURCHASING","ARAP","INVENTORY","BANKING"}.Select(DefinitionFor));
  var pack=await Pack(c,defs);var sections=pack.GetProperty("snapshot").GetProperty("sections").EnumerateArray().ToDictionary(x=>x.GetProperty("kind").GetString()!);
  Assert.Equal(-100,D(sections["PROFIT_LOSS"].GetProperty("metadata").GetProperty("totals").GetProperty("netProfit")));Assert.Equal(0,D(sections["BALANCE_SHEET"].GetProperty("metadata").GetProperty("totals").GetProperty("difference")));Assert.Equal(110,D(sections["AP_AGING"].GetProperty("metadata").GetProperty("totals").GetProperty("netBalance")));
  var supplier=bill.GetProperty("bill").GetProperty("supplierId").GetGuid();var line=Id(bill.GetProperty("lines")[0]);await Expect(await Send(c,HttpMethod.Post,$"/suppliers/{supplier}/payments",new SupplierPaymentInput(110,"BANK_TRANSFER",Code(),Allocations:[new(line,110)])),HttpStatusCode.Created);
  var today=await Today();var native=await Get(c,$"/accounting/reports/payables-aging?asOf={today:yyyy-MM-dd}");Assert.Equal(0,D(native.GetProperty("totals").GetProperty("netBalance")));Assert.Equal(pack.GetRawText(),(await ViewPack(c,Id(pack))).GetRawText());await FinancialReportAssertions.Check(c);
  Task<JsonElement> DefinitionFor(string kind)=>Definition(kind);
 }
 [Fact]public async Task One_pack_statement_keeps_one_snapshot_when_an_expense_commits_mid_capture()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();await Expense(c);var items=JsonSerializer.Serialize(new[]{E(new{definition=await Definition()}),E(new{definition=await Definition("AP_AGING")})});
  await using var gate=new NpgsqlConnection(db.Owner);await gate.OpenAsync();long key=Random.Shared.NextInt64(1,long.MaxValue);await using(var cmd=new NpgsqlCommand("SELECT pg_advisory_lock(@key)",gate)){cmd.Parameters.AddWithValue("key",key);await cmd.ExecuteNonQueryAsync();}
  await using var reader=await db.SessionAsync();var query=Sql.RowsAsync(reader,"WITH gate AS MATERIALIZED(SELECT pg_advisory_xact_lock(@key))SELECT reporting.snapshot('Atomic capture',@items::jsonb,'{}'::jsonb)::text AS body FROM gate",default,("key",key),("items",items));
  try{bool waiting=false;for(int n=0;n<100;n++){waiting=(bool)(await S("SELECT cardinality(pg_blocking_pids(@pid))>0",("pid",reader.Connection.ProcessID)))!;if(waiting)break;await Task.Delay(10);}Assert.True(waiting);await Expense(c,200);}
  finally{await using var cmd=new NpgsqlCommand("SELECT pg_advisory_unlock(@key)",gate);cmd.Parameters.AddWithValue("key",key);await cmd.ExecuteNonQueryAsync();}
  var result=await query;var sections=JsonDocument.Parse((string)result[0]["body"]!).RootElement.GetProperty("sections");Assert.Equal(-100,D(sections[0].GetProperty("metadata").GetProperty("totals").GetProperty("netProfit")));Assert.Equal(110,D(sections[1].GetProperty("metadata").GetProperty("totals").GetProperty("netBalance")));
  var current=await Pack(c,await Definition());Assert.Equal(-300,D(current.GetProperty("snapshot").GetProperty("sections")[0].GetProperty("metadata").GetProperty("totals").GetProperty("netProfit")));
 }
 [Fact]public async Task Permanent_pdf_failure_can_be_manually_retried_without_replacing_frozen_source()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var pack=await Pack(c,await Definition());var job=await Pdf(c,Id(pack));var stub=new Stub{Fail=true,Failure=WorkFailure.Permanent};await Work(stub);var failed=await Get(c,$"/document-jobs/{job}");Assert.Equal("FAILED",failed.GetProperty("state").GetString());await Expect(await Send(c,HttpMethod.Post,$"/document-jobs/{job}/retry",new DocumentRetryInput("Renderer configuration corrected"),V(failed)),HttpStatusCode.Accepted);stub.Fail=false;await Work(stub);Assert.Equal("SUCCEEDED",(await Get(c,$"/document-jobs/{job}")).GetProperty("state").GetString());Assert.Equal(pack.GetProperty("sha256").GetString(),(await ViewPack(c,Id(pack))).GetProperty("sha256").GetString());
 }

